function randomToken(len = 32) {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789';
  let out = '';
  let bytes = null;
  try { bytes = require('crypto').randomBytes(len); } catch (e) { bytes = null; }
