];
const CHECK_TERMS = ['restaurant', 'hotel', 'catering', 'events', 'convenience store', 'supermarket', 'finance', 'leasing', 'insurance', 'investment', 'butcher', 'takeaway', 'deli'];

function halalScreen(...texts) {
